function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100) return 's has 1 to 100 characters.';
  if (!/^[0-9+\-*/()]+$/.test(s)) return 's may only contain digits, + - * / and parentheses.';
  let depth = 0;
  for (const ch of s) {
    if (ch === '(') depth++;
    if (ch === ')') depth--;
    if (depth < 0) return 'Every ) must close an earlier (.';
  }
  if (depth !== 0) return 'Every ( must be closed.';
  return null;
}

