function maxDepth(s) {
  const stack = [];
  let deepest = 0;

  for (const ch of s) {
    if (ch === '(') {
      stack.push(ch);
      deepest = Math.max(deepest, stack.length);
    } else if (ch === ')') {
      stack.pop();
    }
  }
  return deepest;
}

