function maxDepth(s) {
  let answer = 0;
  for (let i = 0; i < s.length; i++) {
    // Depth just after position i: opens minus closes in s[0..i].
    let opens = 0;
    let closes = 0;
    for (let j = 0; j <= i; j++) {
      if (s[j] === '(') opens++;
      if (s[j] === ')') closes++;
    }
    answer = Math.max(answer, opens - closes);
  }
  return answer;
}

