function generate(rand, size) {
  const others = '0123456789+-*/';
  const length = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 12);
  const openBias = size === 'large' ? [0.3, 0.5, 0.75][Math.floor(rand() * 3)] : 0.4;
  let depth = 0;
  let s = '';
  for (let pos = 0; pos < length; pos++) {
    const remaining = length - pos;
    if (depth === remaining) {
      s += ')';
      depth--;
      continue;
    }
    const roll = rand();
    if (roll < openBias && depth + 1 <= remaining - 1) {
      s += '(';
      depth++;
    } else if (roll < openBias + 0.3 && depth > 0) {
      s += ')';
      depth--;
    } else {
      s += others[Math.floor(rand() * others.length)];
    }
  }
  return [s];
}
